SELECT id, amount FROM orders
WHERE created_at >= '2026-03-11'::timestamp
  AND created_at < '2026-03-12'::timestamp;

SELECT COUNT(DISTINCT customer_id) AS n
FROM orders
WHERE created_at >= TIMESTAMP '2026-12-26' AND customer_id IS NOT NULL;

SELECT * FROM emp WHERE sal = 4
UNION
SELECT e.* FROM emp e WHERE sal <> 4 AND NOT EXISTS (SELECT 1 FROM dept d WHERE d.deptno = e.empno);
